// First-party foreground engagement only. No background-tab, paused-video or offscreen credit.
export function trackFeedEngagement(root, items, onCounts = () => {}) {
  const deck=root.querySelector('#fypDeck');if(!deck || !window.IntersectionObserver)return ()=>{};
  const records=new Map(items.map(x=>[x.id,{item:x,sessionId:sessionKey(),watch:0,position:0,slides:new Set(),started:false,starting:false,sending:false,lastSent:0,visible:false,lastVideo:0,video:Array.from(root.querySelectorAll('[data-lesson]')).find(el=>el.dataset.lesson===x.id)?.querySelector('video')}]));
  let active=null,last=performance.now(),closed=false;
  function sessionKey(){const a=new Uint32Array(4);if(window.crypto?.getRandomValues)crypto.getRandomValues(a);else for(let i=0;i<4;i++)a[i]=Math.floor(Math.random()*4294967295);return Array.from(a,n=>n.toString(16).padStart(8,'0')).join('');}
  async function request(id,kind,body){const r=await fetch(`/api/fyp/${encodeURIComponent(id)}/${kind}`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),keepalive:true});if(!r.ok)throw new Error('Engagement not recorded');return r.json();}
  async function send(r,force=false){if(!r||r.watch<1000||r.sending||(!force&&r.started&&r.watch-r.lastSent<4000))return;r.sending=true;try{if(!r.started){await request(r.item.id,'view',{sessionId:r.sessionId});r.started=true;}const result=await request(r.item.id,'watch',{sessionId:r.sessionId,watchMs:Math.floor(r.watch),positionMs:Math.floor(r.position),slidesViewed:[...r.slides]});r.lastSent=r.watch;if(!closed&&result.counts)onCounts(r.item.id,result.counts);}catch{}finally{r.sending=false;}}
  const observer=new IntersectionObserver(entries=>{for(const e of entries){const r=records.get(e.target.dataset.lesson);if(!r)continue;r.visible=e.isIntersecting&&e.intersectionRatio>=.65;if(r.visible){if(active&&active!==r)send(active,true);active=r;r.slides.add(0);r.lastVideo=r.video?.currentTime||0;}else if(active===r){send(r,true);active=null;}}last=performance.now();},{root:deck,threshold:[0,.65,1]});
  root.querySelectorAll('[data-lesson]').forEach(e=>observer.observe(e));
  function tick(){const now=performance.now(),delta=Math.min(1000,Math.max(0,now-last));last=now;if(!active||!active.visible||document.hidden||root.querySelector('.sheet.open')||document.querySelector('.sheet.open'))return;const r=active,v=r.video;if(r.item.format==='reel'){if(!v||v.paused||v.ended||v.seeking||v.readyState<2){if(v?.ended)send(r,true);return;}const advance=v.currentTime-r.lastVideo;r.lastVideo=v.currentTime;if(advance<=0||advance>2)return;r.watch=Math.min(600000,r.watch+Math.min(delta,advance*1000));r.position=Math.max(r.position,v.currentTime*1000);}else r.watch=Math.min(600000,r.watch+delta);send(r);}
  function slide(e){const el=e.target.closest('[data-lesson]'),r=el&&records.get(el.dataset.lesson);if(r&&r===active&&!document.hidden&&Number.isInteger(e.detail?.index))r.slides.add(e.detail.index);}
  function visibility(){for(const r of records.values())send(r,true);last=performance.now();}
  function ended(e){const el=e.target.closest('[data-lesson]'),r=el&&records.get(el.dataset.lesson);if(!r)return;r.position=Math.max(r.position,(e.target.duration||e.target.currentTime||0)*1000);send(r,true);}
  root.addEventListener('fyp:slide',slide);root.addEventListener('ended',ended,true);document.addEventListener('visibilitychange',visibility);window.addEventListener('pagehide',visibility);const timer=setInterval(tick,250);
  return ()=>{closed=true;clearInterval(timer);observer.disconnect();root.removeEventListener('fyp:slide',slide);root.removeEventListener('ended',ended,true);document.removeEventListener('visibilitychange',visibility);window.removeEventListener('pagehide',visibility);for(const r of records.values())send(r,true);};
}
